(7153780, 1097002, 23484, '<td valign="top">That''s a great idea. I just wish it was less expensive.</td>', 'That''s a great idea. I just wish it was less expensive.', '2014-01-07 15:21:32.000000', NULL, 1),
(7153781, 1096910, 173844, '<td valign="top">Elegant.  I like that one puckered pea.</td>', 'Elegant.  I like that one puckered pea.', '2014-01-07 15:24:50.000000', NULL, 1),
(7153797, 1096504, 173844, '<td valign="top">This already attractive photo is given so much more weight by the clever (not inadvertent!) capture of the center cloud so that it appears to be issuing from a volcano.  Now this pleasant day turns ominous as the city below is hideously threatened.</td>', 'This already attractive photo is given so much more weight by the clever (not inadvertent!) capture of the center cloud so that it appears to be issuing from a volcano.  Now this pleasant day turns ominous as the city below is hideously threatened.', '2014-01-07 15:47:52.000000', NULL, 1),
(7153799, 1096744, 173844, '<td valign="top">Clever sculpture.</td>', 'Clever sculpture.', '2014-01-07 15:48:41.000000', NULL, 1),
(7153803, 1096940, 173844, '<td valign="top">The cobwebs of perception?</td>', 'The cobwebs of perception?', '2014-01-07 15:50:50.000000', NULL, 1),
(7153804, 1096952, 173844, '<td valign="top">Very nice representation of energy.</td>', 'Very nice representation of energy.', '2014-01-07 15:52:01.000000', NULL, 1),
(7153811, 1097043, 173844, '<td valign="top">Very nice, serene realization.<br/>Funny, my resolution is just the opposite.</td>', 'Very nice, serene realization.Funny, my resolution is just the opposite.', '2014-01-07 15:57:07.000000', NULL, 1),
(7153817, 1096611, 173844, '<td valign="top">Iconic image with a terrific skyline silhouette and sunburst behind the clouds.  Subtly framed by the tree and minaret.</td>', 'Iconic image with a terrific skyline silhouette and sunburst behind the clouds.  Subtly framed by the tree and minaret.', '2014-01-07 16:00:55.000000', NULL, 1),
(7153826, 1097049, 173844, '<td valign="top">Great resolution and idea, but I''m not sure about the considerable stress on the central goose.  I do like how it sparkles, though.</td>', 'Great resolution and idea, but I''m not sure about the considerable stress on the central goose.  I do like how it sparkles, though.', '2014-01-07 16:08:03.000000', NULL, 1),
(7153832, 1097030, 173844, '<td valign="top">Trudging out of the picture.  New mayor, new mores.</td>', 'Trudging out of the picture.  New mayor, new mores.', '2014-01-07 16:11:41.000000', NULL, 1),
(7153836, 1097050, 173844, '<td valign="top">I like how well this image captures that particular sense of oppression.  The prevalence of newsprint over illustration, and the dreariness of the papers'' tone, add to this impression.</td>', 'I like how well this image captures that particular sense of oppression.  The prevalence of newsprint over illustration, and the dreariness of the papers'' tone, add to this impression.', '2014-01-07 16:18:47.000000', NULL, 1),
(7153837, 1096375, 173844, '<td valign="top">Admirable resolution, marvelously illustrated.  Cheery image.</td>', 'Admirable resolution, marvelously illustrated.  Cheery image.', '2014-01-07 16:21:56.000000', NULL, 1),
(7153854, 1096446, 152252, '<td valign="top">Awwww. That''s sweet.</td>', 'Awwww. That''s sweet.', '2014-01-07 16:44:36.000000', NULL, 1),
(7153925, 1097048, 30049, '<td valign="top">So where are they?</td>', 'So where are they?', '2014-01-07 19:22:08.000000', NULL, 1),
(7154003, 1097048, 150277, '<td valign="top">I like the lighting, and the creativity.</td>', 'I like the lighting, and the creativity.', '2014-01-07 22:10:05.000000', NULL, 1),
(7154005, 1096971, 150277, '<td valign="top">Cute.  Great creativeness!</td>', 'Cute.  Great creativeness!', '2014-01-07 22:11:27.000000', NULL, 1),
