(7154017, 1097010, 150277, '<td valign="top">Ummm, I''m not sure that lock will be effective - but wishing you luck!  (Love the lighting in the photo.)</td>', 'Ummm, I''m not sure that lock will be effective - but wishing you luck!  (Love the lighting in the photo.)', '2014-01-07 22:17:11.000000', NULL, 1),
(7154394, 1097042, 144365, '<td valign="top">Well your crap photo got a nine. <br/>It put a smile on this face.</td>', 'Well your crap photo got a nine. It put a smile on this face.', '2014-01-08 11:27:36.000000', NULL, 1),
(7154395, 1096373, 144365, '<td valign="top">Fine, I''ll oblige.</td>', 'Fine, I''ll oblige.', '2014-01-08 11:27:41.000000', NULL, 1),
(7154482, 1096674, 173844, '<td valign="top">Cuddly fellow.  I''m enjoying the well-lit front of the dog, the part in shadow less so.  The pink tongue is adorable.  The framing racing stripes work well.</td>', 'Cuddly fellow.  I''m enjoying the well-lit front of the dog, the part in shadow less so.  The pink tongue is adorable.  The framing racing stripes work well.', '2014-01-08 14:10:10.000000', NULL, 1),
(7154484, 1096373, 173844, '<td valign="top">Do you hope to foment a revolution or to win the lottery?  Anyway, there''s a nebulous fortitude in this gentleman''s stance.</td>', 'Do you hope to foment a revolution or to win the lottery?  Anyway, there''s a nebulous fortitude in this gentleman''s stance.', '2014-01-08 14:15:18.000000', NULL, 1),
(7154486, 1097031, 173844, '<td valign="top">Well-presented variety of imagery.  I like how the lightning seems to separate the gloom and the light, and give a charge to the crow''s eye.</td>', 'Well-presented variety of imagery.  I like how the lightning seems to separate the gloom and the light, and give a charge to the crow''s eye.', '2014-01-08 14:20:22.000000', NULL, 1),
(7154489, 1096971, 173844, '<td valign="top">Wonderfully silly photo.  I''d like to hear about the further adventures...  Funky shorts.</td>', 'Wonderfully silly photo.  I''d like to hear about the further adventures...  Funky shorts.', '2014-01-08 14:23:59.000000', NULL, 1),
(7154493, 1096350, 173844, '<td valign="top">Wouldn''t that be wonderful.  The brilliant sun, amidst a heavy vignette, is how we may imagine "enlightenment".  The tonal interplay is appealing.</td>', 'Wouldn''t that be wonderful.  The brilliant sun, amidst a heavy vignette, is how we may imagine "enlightenment".  The tonal interplay is appealing.', '2014-01-08 14:28:55.000000', NULL, 1),
(7154494, 1096983, 173844, '<td valign="top">And what''s bigger than a cute child''s imagination?  I especially like the cat in her arms and the girl in the tree.</td>', 'And what''s bigger than a cute child''s imagination?  I especially like the cat in her arms and the girl in the tree.', '2014-01-08 14:31:52.000000', NULL, 1),
(7154601, 1096971, 109227, '<td valign="top">I love it and I hope this gets a blue ribbon!  The sheer entertainment deserves that much.  What a brave soul you are.</td>', 'I love it and I hope this gets a blue ribbon!  The sheer entertainment deserves that much.  What a brave soul you are.', '2014-01-08 19:10:02.000000', NULL, 1),
